struct Token {
    Token * prev;  /* 0x0000 */
    Token * next;  /* 0x0004 */
    int16_t w08;  /* 0x0008 */
    int16_t w0a;  /* 0x000a */
    uint32_t bits[3];  /* 0x000c */
    void * d18;  /* 0x0018 */
    uint32_t d1c;  /* 0x001c */
    char * text;  /* 0x0020 */
    int16_t len;  /* 0x0024 */
    uint8_t unk_0026[0x2];
    char * text2;  /* 0x0028 replacement text emitted instead of `text` */
    char * types;  /* 0x002c per-char split marks: 1 plain, 2 split before, 3 split after */
    uint8_t trail;  /* 0x0030 character that ended the token (emitted after it) */
    uint8_t unk_0031[0x3];
    int16_t w34;  /* 0x0034 */
    int16_t is_number;  /* 0x0036 */
    int32_t num;  /* 0x0038 value of an all-digit token */
};

struct TextIn {
    Engine * engine;  /* 0x0000 */
    int32_t d04;  /* 0x0004 */
    int32_t input_done;  /* 0x0008 engine input ring ran dry */
    int32_t item_done;  /* 0x000c current TextData item fully fed */
    int32_t mode;  /* 0x0010 */
    uint8_t unk_0014[0x4];
    int32_t d18;  /* 0x0018 */
    Token * head;  /* 0x001c */
    Token * tail;  /* 0x0020 */
    Token * cur;  /* 0x0024 tokens up to here are expanded */
    int32_t count;  /* 0x0028 */
    uint8_t unk_002c[0x6];
    int16_t in_quote;  /* 0x0032 mode 4: inside a quoted block */
    int16_t quote_len;  /* 0x0034 length of the detected quote prefix */
    int16_t quote_count;  /* 0x0036 consecutive quoted lines seen */
    char quote_prefix[12];  /* 0x0038 */
    int32_t err[10];  /* 0x0044 */
    int32_t nerr;  /* 0x006c */
};

struct SapiCentral {
    uint8_t unk_0000[0x64];
    int32_t voice;  /* 0x0064 */
    uint8_t mode_info[0xaf0];  /* 0x0068 */
    uint8_t unk_0b58[0x8];
    void * audio_queue;  /* 0x0b60 */
    uint8_t unk_0b64[0x8];
    uint8_t audio_lock[24];  /* 0x0b6c CRITICAL_SECTION */
    uint8_t unk_0b84[0xc];
    int16_t pitch;  /* 0x0b90 */
    uint8_t unk_0b92[0x2];
    int32_t speed;  /* 0x0b94 */
    uint8_t unk_0b98[0x4];
    int32_t volume;  /* 0x0b9c */
    uint8_t unk_0ba0[0xc];
    int32_t ctx;  /* 0x0bac */
    uint8_t unk_0bb0[0x30];
    void * hwnd;  /* 0x0be0 */
    uint8_t unk_0be4[0x2c];
};

